// Builds db/schema.sql: pg_dump --schema-only of a freshly migrated database, made
// deterministic. pg_dump runs inside the PostGIS container, so its version always matches
// the server's and the host needs no PostgreSQL client.

import { spawnSync } from "node:child_process";
import { join } from "node:path";
import { REPO_ROOT } from "./config.ts";

export const SCHEMA_HEADER = `-- GENERATED FILE: do not edit. The schema lives in db/migrations/ (dbmate); this is
-- pg_dump --schema-only of a database with every migration applied, regenerated by
-- \`pnpm db dump\`. CI rebuilds it and fails on a diff. The comments explaining the
-- model are in the migrations.
--
-- Schema only: rows the migrations insert (the map_head row) are not here, so build a
-- database with \`pnpm migrate\`, not from this file.
`;

/** pg_dump's arguments, as dbmate uses them: no owners or grants (they differ between machines). */
export function pgDumpArgs(user: string, database: string): string[] {
  return [
    "pg_dump",
    "--schema-only",
    "--no-owner",
    "--no-privileges",
    "--encoding=UTF8",
    `--username=${user}`,
    `--dbname=${database}`,
  ];
}

/**
 * Runs pg_dump inside the PostGIS container over its local socket. The container is the
 * compose stack's `postgis` service, or the one named by PG_CONTAINER (CI's service
 * container).
 */
export function pgDumpInContainer(user: string, database: string): string {
  const container = process.env["PG_CONTAINER"];
  const args =
    container !== undefined && container !== ""
      ? ["exec", "-i", container, ...pgDumpArgs(user, database)]
      : [
          "compose",
          "--file",
          join(REPO_ROOT, "docker-compose.yml"),
          "exec",
          "-T",
          "postgis",
          ...pgDumpArgs(user, database),
        ];
  const result = spawnSync("docker", args, {
    cwd: REPO_ROOT,
    encoding: "utf8",
    maxBuffer: 64 * 1024 * 1024,
  });
  if (result.error !== undefined) throw result.error;
  if (result.status !== 0) {
    throw new Error(`docker ${args.slice(0, 5).join(" ")} … pg_dump failed:\n${result.stderr}`);
  }
  return result.stdout;
}

/**
 * Makes pg_dump's output deterministic: LF line endings; no version lines (the image's
 * minor version moves); no `\restrict` / `\unrestrict` lines (a new random key on every run,
 * and not SQL); at most one blank line in a row. Appends the applied migrations in dbmate's
 * own dump format, so `dbmate load` would mark them applied.
 */
export function normalizeDump(raw: string, versions: readonly string[]): string {
  const lines = raw
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .filter(
      (line) =>
        !/^\\(un)?restrict\b/.test(line) &&
        !/^-- Dumped (from database|by pg_dump) version /.test(line),
    );
  const body = lines
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  const migrations =
    versions.length === 0
      ? ""
      : `\n\n--\n-- Dbmate schema migrations\n--\n\nINSERT INTO public.schema_migrations (version) VALUES\n${versions
          .map((version) => `    ('${version}')`)
          .join(",\n")};`;
  return `${SCHEMA_HEADER}\n${body}${migrations}\n`;
}
